using System;
using System.Collections.Generic;

class Program
{
    static int[] CountDown(int n)
    {
        List<int> result = new List<int>();
        for (int i = n; i > 0; i--)
        {
            result.Add(i);
        }
        return result.ToArray();
    }
}

