tasks.solution:
using System;
using System.Collections.Generic;

class Program
{
    static string Stairs(int n)
    {
        List<string> rows = new List<string>();
        for (int i = 1; i <= n; i++)
        {
            rows.Add(new string('#', i));
        }
        return string.Join("\n", rows);
    }
}
